(* [comment removed for export] *)
Definition ocbA_W (lo : Z) (sp : word) (ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

Definition ocbA_post (sp gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi P rem src n E b : Z) (es : list mbe) (insz : Z) (bs ej : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists y0 y1 y2 a3x a4x a5x a6x a7x y3 y4 y5 y6 m' (spa ff fp : Z) (gap : list cell) (j0 h32 : list byte),
    ms' = MS (mkR (Z_to_bv 64 P_A_OCB_RET) (Z_to_bv 64 spa) gp tp y0 y1 y2 sp (Z_to_bv 64 spa) (Z_to_bv 64 (P + 232)) (Z_to_bv 64 (spa + 16)) (Z_to_bv 64 E)
                  a3x a4x a5x a6x a7x (Z_to_bv 64 ff) (Z_to_bv 64 E) (Z_to_bv 64 n) (Z_to_bv 64 src) (Z_to_bv 64 rem) (Z_to_bv 64 P)
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 y3 y4 y5 y6)
             F (Z_to_bv 64 P_A_READER_PUT) fc None m' (seg_rom bsegs)
    /\ munch (ocbA_W lo sp ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) /\ spa mod 32 = 0
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H ((1, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' spa (ocb_locals ff src n j0) /\ rw_cells bsegs m' (spa + 32) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 32)
    /\ rw_cells bsegs m' (bv_unsigned sp + -96) (put_saves s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' ff (ocb_ffa spa) /\ rw_cells bsegs m' (ff + 32) [CB 88 h32; C8 (Z_to_bv 64 fp)]
    /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) ocb_sh1 /\ rw_cells bsegs m' fp [C1 (b8 1)]
    /\ rw_cells bsegs m' (P + 232) [C8 (wz b)] /\ rw_cells bsegs m' E [CB 24 ej] /\ bytes_at bsegs m' src bs
    /\ accessible m' (P + 232) 8 /\ accessible m' E 24 /\ accessible m' src n
    /\ AMBuf m' b es insz.

Lemma ocbA : forall (ra sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LF : list fframe) (LB : list block) (s : as_St H)
    (lo shi P rem src n E b : Z) (es : list mbe) (insz : Z) (bs ej : list byte) (r344 : list cell),
  stk bsegs m lo (bv_unsigned sp) -> lo + OCB_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 ->
  mem_inv bsegs m -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  AMBuf m b es insz -> as_RHEAP H s LB m -> aobj LB LF b 64 -> AMBufOwn LB es -> 1 <= n ->
  rw_cells bsegs m (P + 232) [C8 (wz b)] -> aobj LB LF (P + 232) 8 -> accessible m (P + 232) 8 ->
  rw_cells bsegs m E [CB 24 ej] -> aobj LB LF E 24 -> accessible m E 24 ->
  bytes_at bsegs m src bs -> zlength bs = n -> aobj LB LF src n -> accessible m src n ->
  rw_cells bsegs m (P + 336) (C8 (wz 0) :: r344) -> aobj LB LF (P + 336) 8 -> (P + 336) mod 8 = 0 -> accessible m (P + 336) 8 ->
  (P + 336 + Z.of_nat (cells_size (C8 (wz 0) :: r344)) <= lo \/ bv_unsigned sp <= P + 336) ->
